export const WATER_LEVEL = 0;

const POI_FLATS = {
  city: { x: -78, z: -78, r: 58, y: 9.5 },
  base: { x: -115, z: 48, r: 52, y: 13.5 },
  airport: { x: 105, z: -90, r: 68, y: 5.4 },
