  // ============================================================
  const roadPaths = [
    [[-130, -78], [-78, -78], [-30, -78], [40, -84], [103, -90]],
    [[-78, -120], [-78, -78], [-78, -20], [-78, 30], [-100, 48]],
    [[-78, -60], [-20, -30], [40, 10], [82, 70]],
    [[82, 70], [45, 100], [0, 132], [-27, 143]],
    [[126, 8], [100, 40], [82, 70]],
    [[-78, -78], [-40, -105], [-4, -132]],
    [[126, 8], [150, -40], [130, -80], [105, -90]]
  ];
  const roadMat = new THREE.MeshStandardMaterial({ color: 0x333b3c, roughness: 0.98 });
  const roadEdgeMat = new THREE.MeshStandardMaterial({ color: 0x6d6754, roughness: 1 });
  roadPaths.forEach(path => {
    const pts = path.map(([x, z]) => {
      const h = Math.max(terrainHeight(x, z), WATER_LEVEL + 0.1);
      return new THREE.Vector3(x, h + 0.09, z);
    });
    const curve = new THREE.CatmullRomCurve3(pts, false, 'catmullrom', 0.2);
    const N = 90;
    const verts = [], idx = [];
    for (let i = 0; i <= N; i++) {
      const t = i / N;
      const p = curve.getPoint(t);
      const tan = curve.getTangent(t).setY(0).normalize();
      const nx = -tan.z, nz = tan.x;
      const w = 4.2;
      for (const s of [-1, 1]) {
        verts.push(p.x + nx * w * s, p.y, p.z + nz * w * s);
      }
      if (i > 0) {
        const a = (i - 1) * 2;
        idx.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
      }
      if (i % 2 === 0) roadSamples.push({ x: p.x, z: p.z });
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
    geo.setIndex(idx);
    geo.computeVertexNormals();
    const road = new THREE.Mesh(geo, roadMat);
    road.receiveShadow = true;
    group.add(road);
    // dashed center line
    for (let i = 2; i < N - 2; i += 5) {
      const t = i / N;
      const p = curve.getPoint(t);
      const tan = curve.getTangent(t).setY(0).normalize();
      const dash = box(2.4, 0.03, 0.16, new THREE.MeshBasicMaterial({ color: 0xc9b98e }), p.x, p.y + 0.03, p.z);
      dash.rotation.y = Math.atan2(tan.x, tan.z) + Math.PI / 2;
      group.add(dash);
    }
  });

  // ============================================================
  // VEGETATION
  // ============================================================
  function isPOI(x, z, extra = 0) {
    for (const l of LOCATIONS) {
      if (Math.hypot(x - l.x, z - l.z) < l.r * 0.78 + extra) return true;
    }
    return false;
  }
  function roadDist(x, z) {
    let d = 1e9;
    for (const p of roadSamples) {
      const dd = (x - p.x) ** 2 + (z - p.z) ** 2;
      if (dd < d) d = dd;
    }
    return Math.sqrt(d);
  }
  function blocked(x, z, pad = 0) {
    for (const c of colliders) {
      if (x > c.minX - pad && x < c.maxX + pad && z > c.minZ - pad && z < c.maxZ + pad) return true;
    }
    return false;
  }

  const trunkGeo = new THREE.CylinderGeometry(0.22, 0.32, 3.2, 5);
  const crownGeo = new THREE.IcosahedronGeometry(1.8, 1);
  const broad = [];
  let attempts = 0;
  while (broad.length < (low ? 110 : 170) && attempts < 2400) {
    attempts++;
    const x = (rnd() - 0.5) * 370;
    const z = (rnd() - 0.5) * 370;
    const h = terrainHeight(x, z);
    if (h < 1.9 || h > 31) continue;
    if (isPOI(x, z, 2) || roadDist(x, z) < 6 || blocked(x, z, 1.2)) continue;
    broad.push({ x, z, h, s: 0.7 + rnd() * 0.85, c: rnd() });
    if (broad.length < 60) addCollider(x, h, z, 0.9, 4, 0.9);
  }
  const trunkMesh = new THREE.InstancedMesh(trunkGeo, trunkMat, broad.length);
  const crownMesh = new THREE.InstancedMesh(crownGeo, leafMat, broad.length);
  const crownMesh2 = new THREE.InstancedMesh(crownGeo, leafMat2, broad.length);
  const m4 = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const e = new THREE.Euler();
  broad.forEach((t, i) => {
    e.set(0, t.c * 6.28, 0);
    q.setFromEuler(e);
    m4.compose(new THREE.Vector3(t.x, t.h + 1.6 * t.s, t.z), q, new THREE.Vector3(t.s, t.s, t.s));
    trunkMesh.setMatrixAt(i, m4);
    const cs = t.s * (0.8 + t.c * 0.5);
    m4.compose(new THREE.Vector3(t.x, t.h + 3.6 * t.s, t.z), q, new THREE.Vector3(cs * 1.3, cs, cs * 1.3));
    crownMesh.setMatrixAt(i, m4);
    m4.compose(new THREE.Vector3(t.x + 0.7 * t.s, t.h + 4.3 * t.s, t.z - 0.4 * t.s), q, new THREE.Vector3(cs * 0.8, cs * 0.7, cs * 0.8));
    crownMesh2.setMatrixAt(i, m4);
  });
  trunkMesh.castShadow = crownMesh.castShadow = true;
  trunkMesh.receiveShadow = crownMesh.receiveShadow = true;
  group.add(trunkMesh, crownMesh, crownMesh2);

  // pines on high ground
  const pineGeo = new THREE.ConeGeometry(1.5, 5.5, 7);
  const pines = [];
  attempts = 0;
  while (pines.length < (low ? 35 : 65) && attempts < 900) {
    attempts++;
    const x = (rnd() - 0.5) * 360;
    const z = (rnd() - 0.5) * 360;
    const h = terrainHeight(x, z);
    if (h < 18 || isPOI(x, z, 1) || roadDist(x, z) < 6 || blocked(x, z, 1)) continue;
    pines.push({ x, z, h, s: 0.75 + rnd() * 0.6 });
  }
  const pineMesh = new THREE.InstancedMesh(pineGeo, new THREE.MeshStandardMaterial({ color: 0x2f5541, roughness: 0.95 }), pines.length);
  const pineTrunk = new THREE.InstancedMesh(trunkGeo, trunkMat, pines.length);
  pines.forEach((t, i) => {
    e.set(0, t.s * 9, 0); q.setFromEuler(e);
    m4.compose(new THREE.Vector3(t.x, t.h + 1.3 * t.s, t.z), q, new THREE.Vector3(t.s, t.s, t.s));
    pineTrunk.setMatrixAt(i, m4);
    m4.compose(new THREE.Vector3(t.x, t.h + 4.0 * t.s, t.z), q, new THREE.Vector3(t.s, t.s, t.s));
    pineMesh.setMatrixAt(i, m4);
  });
  pineMesh.castShadow = pineTrunk.castShadow = true;
  group.add(pineTrunk, pineMesh);

  // palms near beaches and village
  const palmSpots = [];
  attempts = 0;
  while (palmSpots.length < (low ? 22 : 38) && attempts < 1000) {
    attempts++;
    const x = (rnd() - 0.5) * 360;
    const z = (rnd() - 0.5) * 360;
    const h = terrainHeight(x, z);
    if (h < 1.4 || h > 12) continue;
    if (roadDist(x, z) < 4 || blocked(x, z, 1)) continue;
    if (Math.hypot(x - POI_FLATS.village.x, z - POI_FLATS.village.z) > 50 && Math.hypot(x - POI_FLATS.harbor.x, z - POI_FLATS.harbor.z) > 55 && rnd() > 0.35) continue;
    palmSpots.push({ x, z, h, s: 0.8 + rnd() * 0.6, rot: rnd() * 6.28 });
  }
  const palmTrunkGeo = new THREE.CylinderGeometry(0.16, 0.25, 5.4, 5);
  const palmCrownGeo = new THREE.ConeGeometry(2.2, 1.2, 8, 1, true);
  const palmTrunk = new THREE.InstancedMesh(palmTrunkGeo, trunkMat, palmSpots.length);
  const palmCrown = new THREE.InstancedMesh(palmCrownGeo, new THREE.MeshStandardMaterial({ color: 0x3f804d, roughness: 0.9, side: THREE.DoubleSide }), palmSpots.length);
  palmSpots.forEach((t, i) => {
    e.set(0, t.rot, 0); q.setFromEuler(e);
    m4.compose(new THREE.Vector3(t.x, t.h + 2.7 * t.s, t.z), q, new THREE.Vector3(t.s, t.s, t.s));
    palmTrunk.setMatrixAt(i, m4);
    e.set(0, t.rot + 0.3, 0.12); q.setFromEuler(e);
    m4.compose(new THREE.Vector3(t.x, t.h + 5.7 * t.s, t.z), q, new THREE.Vector3(t.s * 1.2, t.s, t.s * 1.2));
    palmCrown.setMatrixAt(i, m4);
  });
  palmTrunk.castShadow = palmCrown.castShadow = true;
  group.add(palmTrunk, palmCrown);

  // rocks
  const rockGeo = new THREE.DodecahedronGeometry(1, 0);
  const rockMat = new THREE.MeshStandardMaterial({ color: 0x63695f, roughness: 1 });
  const rocks = [];
  attempts = 0;
  while (rocks.length < (low ? 45 : 85) && attempts < 800) {
    attempts++;
    const x = (rnd() - 0.5) * 380;
    const z = (rnd() - 0.5) * 380;
    const h = terrainHeight(x, z);
    if (h < 0.5 || isPOI(x, z, 0) || roadDist(x, z) < 5 || blocked(x, z, 1)) continue;
    rocks.push({ x, z, h, s: 0.3 + rnd() * 1.7, r: rnd() * 6.28 });
  }
  const rockMesh = new THREE.InstancedMesh(rockGeo, rockMat, rocks.length);
  rocks.forEach((t, i) => {
    e.set(t.r * 0.4, t.r, t.r * 0.3); q.setFromEuler(e);
    m4.compose(new THREE.Vector3(t.x, t.h + t.s * 0.3, t.z), q, new THREE.Vector3(t.s * 1.4, t.s, t.s));
    rockMesh.setMatrixAt(i, m4);
  });
  rockMesh.castShadow = rockMesh.receiveShadow = true;
  group.add(rockMesh);

  // bushes
  const bushGeo = new THREE.IcosahedronGeometry(0.72, 0);
  const bushes = [];
  for (let i = 0; i < (low ? 90 : 180); i++) {
    const x = (rnd() - 0.5) * 360;
    const z = (rnd() - 0.5) * 360;
    const h = terrainHeight(x, z);
    if (h < 1.6 || h > 32 || isPOI(x, z, 0) || roadDist(x, z) < 4 || blocked(x, z, 0.5)) continue;
    bushes.push({ x, z, h, s: 0.5 + rnd() * 0.9 });
  }
  const bushMesh = new THREE.InstancedMesh(bushGeo, new THREE.MeshStandardMaterial({ color: 0x426b3d, roughness: 1 }), bushes.length);
  bushes.forEach((t, i) => {
    e.set(0, t.s * 4, 0); q.setFromEuler(e);
    m4.compose(new THREE.Vector3(t.x, t.h + 0.5 * t.s, t.z), q, new THREE.Vector3(t.s, t.s * 0.7, t.s));
    bushMesh.setMatrixAt(i, m4);
  });
  bushMesh.castShadow = true;
  group.add(bushMesh);

  // grass tufts around low ground (cheap crossed cones)
  if (!low) {
    const grassGeo = new THREE.ConeGeometry(0.12, 0.7, 3);
    const grassMat = new THREE.MeshStandardMaterial({ color: 0x718c4c, roughness: 1 });
    const tufts = [];
    for (let i = 0; i < 700; i++) {
      const x = (rnd() - 0.5) * 340;
      const z = (rnd() - 0.5) * 340;
      const h = terrainHeight(x, z);
      if (h < 2.2 || h > 26 || isPOI(x, z, 0) || roadDist(x, z) < 4) continue;
      tufts.push({ x, z, h });
    }
    const grassMesh = new THREE.InstancedMesh(grassGeo, grassMat, tufts.length);
    tufts.forEach((t, i) => {
      m4.makeScale(0.8 + rnd(), 0.7 + rnd() * 1.4, 0.8 + rnd());
      m4.setPosition(t.x, t.h + 0.35, t.z);
      grassMesh.setMatrixAt(i, m4);
    });
    group.add(grassMesh);
  }

  // ============================================================
  // CLOUDS + BIRDS
  // ============================================================
  const cloudTex = makeGlowTexture('rgba(255,246,238,.95)', 'rgba(255,246,238,0)', 128);
  const clouds = [];
  for (let i = 0; i < 16; i++) {
    const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: cloudTex, color: 0xffe6d2, transparent: true, opacity: 0.2 + rnd() * 0.16, depthWrite: false, fog: true }));
    const a = rnd() * 6.28, rad = 100 + rnd() * 250;
    s.position.set(Math.cos(a) * rad, 78 + rnd() * 65, Math.sin(a) * rad);
    const sc = 55 + rnd() * 85;
    s.scale.set(sc * 1.8, sc * 0.55, 1);
    group.add(s);
    clouds.push({ s, speed: 0.25 + rnd() * 0.4, x: s.position.x, z: s.position.z });
  }
  const birds = [];
  const birdMat = new THREE.LineBasicMaterial({ color: 0x1f3438, transparent: true, opacity: 0.5 });
  for (let i = 0; i < 7; i++) {
    const g = new THREE.Group();
    for (const side of [-1, 1]) {
      const geo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), new THREE.Vector3(side * 0.45, 0.12, 0)]);
      g.add(new THREE.Line(geo, birdMat));
    }
    const a = rnd() * 6.28, rad = 40 + rnd() * 90;
    g.position.set(Math.cos(a) * rad, 22 + rnd() * 18, Math.sin(a) * rad);
    g.userData = { a, rad, speed: 0.07 + rnd() * 0.05, y: g.position.y };
    group.add(g);
    birds.push(g);
  }

  // ============================================================
  // VEHICLES
  // ============================================================
  function createATV(x, z, yaw = 0, color = 0xd86a2b) {
    const y = terrainHeight(x, z);
    const g = new THREE.Group();
    const bodyMat = new THREE.MeshStandardMaterial({ color, roughness: 0.5, metalness: 0.35 });
    const chassy = box(1.5, 0.5, 2.7, darkMat, 0, 0.55, 0);
    g.add(chassy);
    const hood = box(1.2, 0.55, 1.0, bodyMat, 0, 0.95, -0.7);
    g.add(hood);
    const seat = box(1.1, 0.45, 1.0, darkMat, 0, 0.95, 0.25);
    g.add(seat);
    const cageMat = new THREE.MeshStandardMaterial({ color: 0x313b3e, roughness: 0.4, metalness: 0.7 });
    for (const [cx, cz] of [[-0.55, 0.65], [0.55, 0.65], [-0.55, -0.3], [0.55, -0.3]]) {
      const bar = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 1.5, 5), cageMat);
      bar.position.set(cx, 1.55, cz);
      bar.rotation.z = cx * 0.25;
      g.add(bar);
    }
    const top = box(1.1, 0.08, 0.16, cageMat, 0, 2.25, 0.35);
    g.add(top);
    const wheels = [];
    const wheelGeo = new THREE.CylinderGeometry(0.44, 0.44, 0.32, 12);
    const wheelMat = new THREE.MeshStandardMaterial({ color: 0x141719, roughness: 0.98 });
    for (const [wx, wz] of [[-0.82, -0.95], [0.82, -0.95], [-0.82, 0.95], [0.82, 0.95]]) {
      const w = new THREE.Mesh(wheelGeo, wheelMat);
      w.rotation.z = Math.PI / 2;
      w.position.set(wx, 0.45, wz);
      w.castShadow = true;
      g.add(w);
      wheels.push(w);
    }
    const light = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.15, 0.1), new THREE.MeshBasicMaterial({ color: 0xffe0a8 }));
    light.position.set(0, 1.0, -1.22);
    g.add(light);
    g.position.set(x, y, z);
    g.rotation.y = yaw;
    g.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
    group.add(g);
    const v = { group: g, x, z, y, yaw, wheels, radius: 1.5, name: 'RAPTOR ATV', occupied: false };
    vehicles.push(v);
    return v;
  }
  createATV(30, -60, 1.2);
  createATV(64, 44, 0.3, 0x3f7b78);
  createATV(-84, 24, 2.3, 0xb54a2b);
  createATV(92, -40, 0.9, 0x9a7b36);
  createATV(-5, 92, 1.9, 0x4b6f80);

  // ============================================================
  // LOOT SPAWNS
  // ============================================================
  const spawnPools = [
    { x: POI_FLATS.city.x, z: POI_FLATS.city.z, r: 38, n: 16 },
    { x: POI_FLATS.airport.x, z: POI_FLATS.airport.z, r: 35, n: 11 },
    { x: POI_FLATS.base.x, z: POI_FLATS.base.z, r: 31, n: 11 },
    { x: POI_FLATS.village.x, z: POI_FLATS.village.z, r: 28, n: 10 },
    { x: POI_FLATS.industrial.x, z: POI_FLATS.industrial.z, r: 27, n: 9 },
    { x: POI_FLATS.harbor.x, z: POI_FLATS.harbor.z, r: 30, n: 10 },
    { x: POI_FLATS.bunker.x, z: POI_FLATS.bunker.z, r: 22, n: 6 },
    { x: POI_FLATS.mountain.x, z: POI_FLATS.mountain.z, r: 20, n: 4 },
    { x: POI_FLATS.lake.x, z: POI_FLATS.lake.z, r: 22, n: 5 },
    { x: 0, z: -40, r: 80, n: 10 }
  ];
  const qualityTable = ['common', 'common', 'uncommon', 'uncommon', 'rare', 'rare', 'epic'];
  spawnPools.forEach((pool, pi) => {
    for (let i = 0; i < pool.n; i++) {
      let tries = 0, x, z;
      do {
        const a = rnd() * 6.28, rad = Math.sqrt(rnd()) * pool.r;
        x = pool.x + Math.cos(a) * rad;
        z = pool.z + Math.sin(a) * rad;
        tries++;
      } while (tries < 30 && (blocked(x, z, 1.2) || terrainHeight(x, z) < 0.8));
      lootSpawns.push({
        x, z, y: terrainHeight(x, z),
        quality: qualityTable[Math.min(qualityTable.length - 1, Math.floor(rnd() * qualityTable.length))],
        tier: pi < 3 ? 1.1 : 1
      });
    }
  });

  // Player spawns
  const spawnPoints = [
    { x: -25, z: -110, yaw: -2.6, name: 'SUNSET CITY' },
    { x: -80, z: 4, yaw: 1.0, name: 'IRON RIDGE BASE' },
    { x: 55, z: 52, yaw: 0.5, name: 'PALM VILLAGE' },
    { x: 58, z: -74, yaw: -0.9, name: 'SKYLINE AIRFIELD' },
    { x: 95, z: 15, yaw: 1.8, name: 'FOUNDRY YARD' },
    { x: -20, z: 100, yaw: 3.0, name: 'KESTREL HARBOR' },
    { x: -4, z: -110, yaw: 0, name: 'ECHO BUNKER' }
  ];
  spawnPoints.forEach(p => { p.y = terrainHeight(p.x, p.z); });

  // Sun target follows player later via game
  const update = (dt, t) => {
    waterUniforms.uTime.value = t;
    for (const c of clouds) {
      c.s.position.x = c.x + Math.sin(t * 0.004 * c.speed + c.x) * 35;
    }
    for (const b of birds) {
      const a = b.userData.a + t * b.userData.speed;
      b.position.x = Math.cos(a) * b.userData.rad;
      b.position.z = Math.sin(a) * b.userData.rad;
      b.position.y = b.userData.y + Math.sin(t * 1.2 + b.userData.rad) * 0.8;
      b.rotation.y = -a - Math.PI / 2;
    }
    sunSprite.position.copy(sunDir).multiplyScalar(680);
  };

  function raycastWorld(origin, dir, maxDist) {
    // Ray vs terrain (coarse march), water surface and solid AABBs.
    let best = maxDist;
    let hit = null;
    const step = 1.2;
    for (let t = 0; t < maxDist; t += step) {
      const x = origin.x + dir.x * t;
      const y = origin.y + dir.y * t;
      const z = origin.z + dir.z * t;
      if (y <= terrainHeight(x, z) && y < 60) {
        best = t;
        hit = { type: 'terrain', point: new THREE.Vector3(x, y, z), distance: t };
        break;
      }
      if (y <= WATER_LEVEL) {
        best = t;
        hit = { type: 'water', point: new THREE.Vector3(x, y, z), distance: t };
        break;
      }
    }
    for (const c of colliders) {
      const t = rayAABB(origin, dir, c, best);
      if (t !== null && t < best) {
        best = t;
        hit = { type: 'structure', point: new THREE.Vector3(origin.x + dir.x * t, origin.y + dir.y * t, origin.z + dir.z * t), distance: t, collider: c };
      }
    }
    return hit;
  }

  function rayAABB(o, d, c, maxDist) {
    let tmin = 0, tmax = maxDist;
    for (const axis of ['x', 'y', 'z']) {
      const min = axis === 'x' ? c.minX : axis === 'y' ? c.minY : c.minZ;
      const max = axis === 'x' ? c.maxX : axis === 'y' ? c.maxY : c.maxZ;
      const od = axis === 'x' ? o.x : axis === 'y' ? o.y : o.z;
      const dd = axis === 'x' ? d.x : axis === 'y' ? d.y : d.z;
      if (Math.abs(dd) < 1e-8) {
        if (od < min || od > max) return null;
      } else {
        let t1 = (min - od) / dd, t2 = (max - od) / dd;
        if (t1 > t2) [t1, t2] = [t2, t1];
        tmin = Math.max(tmin, t1);
        tmax = Math.min(tmax, t2);
        if (tmin > tmax) return null;
      }
    }
    return tmin;
  }

  return {
    group, colliders, surfaces, lootSpawns, vehicles, landmarks, spawnPoints,
    heightAt: terrainHeight, waterLevel: WATER_LEVEL, sun, sunSprite, sky, update, raycastWorld, rayAABB
  };
}

import * as THREE from 'three';
import { makeGlowTexture } from './models.js';
import { makeCanvas } from './utils.js';

const glow = {};
function getGlow(color) {
  if (!glow[color]) glow[color] = makeGlowTexture(color, 'rgba(0,0,0,0)', 64);
  return glow[color];
}

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.items = [];
    this.tracers = [];
    this.texts = [];
    this.impactTex = makeGlowTexture('rgba(255,220,170,1)', 'rgba(255,120,30,0)', 64);
    this.bloodTex = makeGlowTexture('rgba(220,54,34,1)', 'rgba(100,5,0,0)', 64);
    this.sparkTex = makeGlowTexture('rgba(255,236,190,1)', 'rgba(255,140,30,0)', 32);
  }

  tracer(from, to, color = 0xffc86b) {
    const geo = new THREE.BufferGeometry().setFromPoints([from.clone(), to.clone()]);
    const mat = new THREE.LineBasicMaterial({ color, transparent: true, opacity: 0.92, blending: THREE.AdditiveBlending, depthWrite: false });
    const line = new THREE.Line(geo, mat);
    line.renderOrder = 5;
    this.scene.add(line);
    this.tracers.push({ obj: line, life: 0.085, max: 0.085 });
  }

  muzzle(pos, color = 0xffb15e, scale = 1) {
    const mat = new THREE.SpriteMaterial({ map: this.sparkTex, color, transparent: true, opacity: 1, depthWrite: false, blending: THREE.AdditiveBlending });
    const s = new THREE.Sprite(mat);
    s.position.copy(pos);
    s.scale.setScalar(0.7 * scale);
    this.scene.add(s);
    this.items.push({ obj: s, life: 0.055, max: 0.055, grow: 2.2 });
    const light = new THREE.PointLight(color, 1.2, 6, 2);
    light.position.copy(pos);
    this.scene.add(light);
    this.items.push({ obj: light, light: true, life: 0.06, max: 0.06 });
  }

  impact(point, normal, kind = 'world') {
    const tex = kind === 'flesh' ? this.bloodTex : this.impactTex;
    const mat = new THREE.SpriteMaterial({ map: tex, color: kind === 'flesh' ? 0xffffff : 0xffc38a, transparent: true, opacity: 0.9, depthWrite: false, blending: kind === 'flesh' ? THREE.NormalBlending : THREE.AdditiveBlending });
    const s = new THREE.Sprite(mat);
    s.position.copy(point);
    s.scale.setScalar(kind === 'flesh' ? 0.5 : 0.38);
    this.scene.add(s);
    this.items.push({ obj: s, life: 0.16, max: 0.16, grow: 1.5 });
    const n = kind === 'flesh' ? 5 : 7;
    for (let i = 0; i < n; i++) {
      const m = new THREE.Mesh(new THREE.BoxGeometry(0.025, 0.025, 0.025), new THREE.MeshBasicMaterial({ color: kind === 'flesh' ? 0x9b1d10 : 0xffd49a, transparent: true }));
      m.position.copy(point);
      const v = new THREE.Vector3((Math.random() - 0.5) * 2.2, Math.random() * 2.2, (Math.random() - 0.5) * 2.2);
      if (normal) v.addScaledVector(normal, 1.0);
      this.scene.add(m);
      this.items.push({ obj: m, life: 0.3 + Math.random() * 0.2, max: 0.5, vel: v, gravity: true, fade: true });
    }
  }

  damageNumber(pos, amount, crit = false) {
    const c = makeCanvas(128, 64);
    const ctx = c.getContext('2d');
    ctx.font = `700 ${crit ? 38 : 31}px "Arial Narrow", Arial`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.strokeStyle = 'rgba(0,0,0,.8)';
    ctx.lineWidth = 6;
    ctx.strokeText(String(amount), 64, 32);
    ctx.fillStyle = crit ? '#ffb44e' : '#ffffff';
    ctx.fillText(String(amount), 64, 32);
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, depthTest: false }));
    sp.position.copy(pos);
    sp.scale.set(0.9, 0.45, 1);
    sp.renderOrder = 20;
    this.scene.add(sp);
    this.items.push({ obj: sp, life: 0.75, max: 0.75, rise: 1.0, fade: true, damageText: true });
  }

  explosion(pos, radius = 6) {
    const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.impactTex, color: 0xffb15e, transparent: true, opacity: 1, depthWrite: false, blending: THREE.AdditiveBlending }));
    s.position.copy(pos);
    s.scale.setScalar(2.5);
    this.scene.add(s);
    this.items.push({ obj: s, life: 0.45, max: 0.45, grow: 9, fade: true });
    const ringGeo = new THREE.RingGeometry(0.3, 0.55, 32);
    const ring = new THREE.Mesh(ringGeo, new THREE.MeshBasicMaterial({ color: 0xffc07b, transparent: true, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending }));
    ring.position.copy(pos);
    ring.rotation.x = -Math.PI / 2;
    ring.scale.setScalar(1);
    ring.renderOrder = 6;
    this.scene.add(ring);
    this.items.push({ obj: ring, life: 0.55, max: 0.55, grow: radius * 2.2, fade: true });
    for (let i = 0; i < 22; i++) {
      const m = new THREE.Mesh(new THREE.IcosahedronGeometry(0.06 + Math.random() * 0.08, 0), new THREE.MeshBasicMaterial({ color: Math.random() > 0.5 ? 0x2b2018 : 0xffa449, transparent: true }));
      m.position.copy(pos);
      const a = Math.random() * Math.PI * 2, up = 2 + Math.random() * 7;
      this.scene.add(m);
      this.items.push({ obj: m, life: 0.6 + Math.random() * 0.6, max: 1.2, vel: new THREE.Vector3(Math.cos(a) * (2 + Math.random() * 5), up, Math.sin(a) * (2 + Math.random() * 5)), gravity: true, fade: true });
    }
    const light = new THREE.PointLight(0xff8a3d, 12, 30, 2);
    light.position.copy(pos);
    light.position.y += 1;
    this.scene.add(light);
    this.items.push({ obj: light, light: true, life: 0.25, max: 0.25, startIntensity: 12 });
  }

  update(dt) {
    for (let i = this.tracers.length - 1; i >= 0; i--) {
      const t = this.tracers[i];
      t.life -= dt;
      t.obj.material.opacity = Math.max(0, t.life / t.max);
      if (t.life <= 0) {
        this.scene.remove(t.obj);
        t.obj.geometry.dispose();
        t.obj.material.dispose();
        this.tracers.splice(i, 1);
      }
    }
    for (let i = this.items.length - 1; i >= 0; i--) {
      const it = this.items[i];
      it.life -= dt;
      const p = Math.max(0, it.life / it.max);
      if (it.life <= 0) {
        this.scene.remove(it.obj);
        if (it.obj.geometry) it.obj.geometry.dispose();
        if (it.obj.material) {
          if (it.obj.material.map && !it.obj.userData?.sharedTex) it.obj.material.map.dispose();
          it.obj.material.dispose();
        }
        this.items.splice(i, 1);
        continue;
      }
      if (it.light) {
        it.obj.intensity = (it.startIntensity ?? 1.2) * p;
      } else {
        if (it.fade && it.obj.material) it.obj.material.opacity = p;
        if (it.grow) {
          if (it.damageText) {
            it.obj.position.y += it.rise * dt;
            const sc = Math.min(1, p * 1.3);
            it.obj.scale.set(0.9 * sc, 0.45 * sc, 1);
          } else if (it.obj.isMesh && it.obj.geometry.type === 'RingGeometry') {
            it.obj.scale.setScalar(1 + (1 - p) * 12);
          } else {
            it.obj.scale.setScalar(Math.max(0.05, (1 + (1 - p) * it.grow)));
          }
        }
        if (it.vel) {
          it.obj.position.addScaledVector(it.vel, dt);
          if (it.gravity) it.vel.y -= 9.8 * dt;
          if (it.obj.material) it.obj.material.opacity = p;
        }
      }
    }
  }
}

export function spawnSmoke(scene, pos) {
  const tex = makeGlowTexture('rgba(110,110,105,.55)', 'rgba(60,60,60,0)', 64);
  for (let i = 0; i < 5; i++) {
    const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, opacity: 0.35, depthWrite: false }));
    s.position.copy(pos).add(new THREE.Vector3((Math.random() - 0.5) * 2, Math.random() * 2, (Math.random() - 0.5) * 2));
    s.scale.setScalar(1 + Math.random() * 2);
    scene.add(s);
    const start = performance.now();
    const drift = new THREE.Vector3((Math.random() - 0.5) * 0.3, 0.7 + Math.random() * 0.5, (Math.random() - 0.5) * 0.3);
    const anim = () => {
      const t = (performance.now() - start) / 1000;
      if (t > 2.4) { scene.remove(s); s.material.dispose(); return; }
      s.position.addScaledVector(drift, 1 / 60);
      s.material.opacity = 0.3 * (1 - t / 2.4);
      s.scale.setScalar(1 + t * 2);
      requestAnimationFrame(anim);
    };
    anim();
  }
}

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.ambience = null;
    this.lastUi = 0;
  }

  ensure() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return this.ctx;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.65;
    this.master.connect(this.ctx.destination);
    this.noise = this.makeNoise(1.4);
    this.startAmbience();
    return this.ctx;
  }

  makeNoise(seconds) {
    const ctx = this.ctx;
    const buffer = ctx.createBuffer(1, ctx.sampleRate * seconds, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  startAmbience() {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 380;
    filter.Q.value = 0.4;
    const gain = ctx.createGain();
    gain.gain.value = 0.035;
    src.connect(filter).connect(gain).connect(this.master);
    src.start();
    this.ambience = { src, gain };
    // Warm menu pad
    const padGain = ctx.createGain();
    padGain.gain.value = 0.012;
    padGain.connect(this.master);
    [55, 82.5, 110, 164.8].forEach((f, i) => {
      const o = ctx.createOscillator();
      o.type = i % 2 ? 'sine' : 'triangle';
      o.frequency.value = f;
      const g = ctx.createGain();
      g.gain.value = i === 0 ? 0.6 : 0.22;
      o.connect(g).connect(padGain);
      o.start();
      const lfo = ctx.createOscillator();
      lfo.frequency.value = 0.03 + i * 0.017;
      const lg = ctx.createGain();
      lg.gain.value = 0.003;
      lfo.connect(lg).connect(padGain.gain);
      lfo.start();
    });
    this.padGain = padGain;
  }

  setMuted(m) {
    this.muted = m;
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(m ? 0 : 0.65, this.ctx.currentTime, 0.04);
    }
  }

  noiseBurst(duration, freq, gain, type = 'lowpass', q = 0.7, when = 0) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx, t = ctx.currentTime + when;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    const f = ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(freq, t);
    f.frequency.exponentialRampToValueAtTime(Math.max(60, freq * 0.22), t + duration);
    f.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.003);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    src.connect(f).connect(g).connect(this.master);
    src.start(t);
    src.stop(t + duration + 0.03);
  }

  tone(freq, duration, gain, type = 'sine', when = 0, endFreq = null) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx, t = ctx.currentTime + when;
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (endFreq) o.frequency.exponentialRampToValueAtTime(endFreq, t + duration);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    o.connect(g).connect(this.master);
    o.start(t);
    o.stop(t + duration + 0.03);
  }

  shot(kind = 'ar', dist = 0) {
    if (!this.ctx || this.muted) return;
    const vol = Math.max(0.03, 0.42 / (1 + dist * 0.035));
    if (kind === 'sniper') {
      this.noiseBurst(0.36, 2600, vol * 1.4, 'bandpass', 0.8);
      this.tone(98, 0.24, vol * 0.7, 'sawtooth', 0, 34);
      this.noiseBurst(0.9, 280, vol * 0.35, 'lowpass', 0.5, 0.05);
    } else if (kind === 'shotgun') {
      this.noiseBurst(0.3, 1600, vol * 1.5, 'lowpass', 0.7);
      this.tone(72, 0.28, vol * 0.85, 'sawtooth', 0, 28);
    } else if (kind === 'smg') {
      this.noiseBurst(0.1, 3400, vol * 0.9, 'bandpass', 1.1);
      this.tone(145, 0.08, vol * 0.35, 'square', 0, 50);
    } else if (kind === 'pistol') {
      this.noiseBurst(0.15, 2300, vol * 1.0, 'bandpass', 0.9);
      this.tone(120, 0.1, vol * 0.45, 'square', 0, 45);
    } else if (kind === 'melee') {
      this.noiseBurst(0.12, 1200, vol * 0.5, 'highpass', 0.5);
    } else {
      this.noiseBurst(0.13, 2800, vol * 1.05, 'bandpass', 1.0);
      this.tone(116, 0.09, vol * 0.38, 'square', 0, 44);
    }
  }

  reload() {
    this.noiseBurst(0.05, 3000, 0.11, 'highpass', 1, 0.02);
    this.tone(420, 0.03, 0.035, 'square', 0.15);
    this.noiseBurst(0.06, 2200, 0.12, 'highpass', 1, 0.6);
    this.tone(610, 0.04, 0.03, 'square', 0.65);
  }

  hit(crit = false) {
    this.tone(crit ? 980 : 720, 0.055, 0.1, 'sine');
    this.tone(crit ? 1420 : 1100, 0.05, 0.07, 'sine', 0.015);
  }

  hitTaken() {
    this.noiseBurst(0.12, 600, 0.14, 'lowpass');
    this.tone(74, 0.14, 0.09, 'sine', 0, 45);
  }

  pickup() {
    this.tone(520, 0.09, 0.06, 'triangle');
    this.tone(780, 0.12, 0.05, 'triangle', 0.07);
    this.tone(1040, 0.16, 0.04, 'sine', 0.14);
  }

  ui() {
    if (!this.ctx) return;
    const now = performance.now();
    if (now - this.lastUi < 45) return;
    this.lastUi = now;
    this.tone(840, 0.03, 0.035, 'square');
  }

  zoneAlert() {
    this.tone(240, 0.28, 0.07, 'sawtooth', 0, 180);
    this.tone(240, 0.28, 0.07, 'sawtooth', 0.38, 180);
  }

  eliminated() {
    this.tone(620, 0.15, 0.1, 'sine');
    this.tone(440, 0.18, 0.1, 'sine', 0.12);
    this.tone(260, 0.45, 0.12, 'sine', 0.28);
  }

  victory() {
    [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.45, 0.09, 'triangle', i * 0.12));
  }

  explosion(dist = 0) {
    const vol = Math.max(0.05, 0.65 / (1 + dist * 0.02));
    this.noiseBurst(0.75, 1000, vol, 'lowpass', 0.6);
    this.tone(52, 0.8, vol * 0.9, 'sawtooth', 0, 24);
  }

  throwGrenade() {
    this.noiseBurst(0.15, 900, 0.06, 'highpass');
  }

  heal() {
    this.tone(330, 0.2, 0.04, 'sine');
    this.tone(440, 0.25, 0.04, 'sine', 0.16);
    this.tone(660, 0.4, 0.03, 'sine', 0.34);
  }
}

import * as THREE from 'three';
import { WEAPONS, OPERATORS, MATCH } from './data.js';
import { clamp, damp, lerp, dampAngle } from './utils.js';
import { createOperator, createWeaponModel, createParachute } from './models.js';

const UP = new THREE.Vector3(0, 1, 0);

export class Player {
  constructor(scene, world, operatorId = 'raven') {
    this.scene = scene;
    this.world = world;
    this.operatorId = operatorId;
    this.palette = OPERATORS[operatorId] || OPERATORS.raven;
    this.character = createOperator(this.palette);
    this.character.visible = false;
    scene.add(this.character);
    this.position = new THREE.Vector3(0, 10, 0);
    this.velocity = new THREE.Vector3();
    this.yaw = 0;
    this.pitch = 0;
    this.recoilPitch = 0;
    this.recoilYaw = 0;
    this.health = MATCH.maxHealth;
    this.armor = 0;
    this.maxArmor = 50;
    this.alive = true;
    this.isSwimming = false;
    this.grounded = true;
    this.crouching = false;
    this.sprinting = false;
    this.aiming = false;
    this.moveAmount = 0;
    this.walkPhase = 0;
    this.radius = 0.38;
    this.slots = [
      { id: 'ar', mag: 30, reserve: 90, rarity: 'rare', attachments: ['HOLO'] },
      { id: 'pistol', mag: 15, reserve: 45, rarity: 'common', attachments: [] },
      { id: 'melee', mag: 1, reserve: 0, rarity: 'common', attachments: [] }
    ];
    this.currentSlot = 0;
    this.fireCooldown = 0;
    this.reloadTimer = 0;
    this.reloadTotal = 0;
    this.switchTimer = 0;
    this.medkits = 2;
    this.grenades = 1;
    this.packUsed = 3;
    this.packMax = 8;
    this.aimAmount = 0;
    this.healTimer = 0;
    this.healTotal = 0;
    this.damageDealt = 0;
    this.kills = 0;
    this.cameraShake = 0;
    this.weaponModel = null;
    this.chute = null;
    this.dropTime = 0;
    this.dropping = false;
    this.deathTime = 0;
    this.lastDamageTime = 0;
    this.footstepTimer = 0;
    this._camPos = new THREE.Vector3();
    this._camDir = new THREE.Vector3();
    this._target = new THREE.Vector3();
    this.updateWeaponModel();
  }

  setOperator(id) {
    if (!OPERATORS[id] || id === this.operatorId) return;
    this.operatorId = id;
    this.palette = OPERATORS[id];
    const parent = this.character.parent;
    parent.remove(this.character);
    this.character = createOperator(this.palette);
    parent.add(this.character);
    this.character.position.copy(this.position);
    this.character.rotation.y = this.yaw;
    this.updateWeaponModel();
  }

  get weapon() { return WEAPONS[this.slots[this.currentSlot].id]; }
  get slot() { return this.slots[this.currentSlot]; }

  updateWeaponModel() {
    if (this.weaponModel) {
      this.character.userData.weaponMount.remove(this.weaponModel);
      this.weaponModel.traverse(o => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) {
          if (Array.isArray(o.material)) o.material.forEach(m => m.dispose());
          else o.material.dispose();
        }
      });
      this.weaponModel = null;
    }
    const w = this.weapon;
    if (!w) return;
    const model = createWeaponModel(w.id, this.palette.accent, w.id === 'pistol' ? 0.9 : 0.78);
    this.character.userData.weaponMount.add(model);
    this.weaponModel = model;
  }

  spawn(point) {
    this.position.set(point.x, point.y + 0.1, point.z);
    this.yaw = point.yaw ?? 0;
    this.pitch = -0.02;
    this.health = MATCH.maxHealth;
    this.armor = 0;
    this.alive = true;
    this.character.visible = true;
    this.character.position.copy(this.position);
    this.character.rotation.y = this.yaw;
    this.velocity.set(0, 0, 0);
    this.slots[0] = { id: 'ar', mag: 30, reserve: 90, rarity: 'rare', attachments: ['HOLO'] };
    this.slots[1] = { id: 'pistol', mag: 15, reserve: 45, rarity: 'common', attachments: [] };
    this.currentSlot = 0;
    this.updateWeaponModel();
    this.medkits = 2;
    this.grenades = 1;
    this.packUsed = 3;
    this.healTimer = 0;
    this.reloadTimer = 0;
  }

  startDrop(point, height = 62) {
    this.spawn(point);
    this.position.y = point.y + height;
    this.character.position.copy(this.position);
    this.dropping = true;
    this.dropTime = 0;
    this.alive = true;
    this.health = MATCH.maxHealth;
    this.chute = createParachute(this.palette.accent);
    this.chute.position.y = 0.45;
    this.character.add(this.chute);
    this.aiming = false;
  }

  finishDrop() {
    if (this.chute) {
      this.character.remove(this.chute);
      this.chute.traverse(o => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) {
          if (o.material.map) o.material.map.dispose();
          o.material.dispose();
        }
      });
      this.chute = null;
    }
    this.dropping = false;
    this.position.y = this.groundHeight(this.position.x, this.position.z) + 0.05;
    this.character.position.copy(this.position);
  }

  updateDrop(dt, t, targetY) {
    this.dropTime += dt;
    const t0 = Math.min(1, this.dropTime / 3.2);
    const eased = 1 - Math.pow(1 - t0, 3);
    const startY = targetY + 62;
    this.position.y = lerp(startY, targetY + 0.1, eased);
    this.position.x += Math.sin(t * 0.7) * dt * 1.3;
    this.position.z += Math.cos(t * 0.6) * dt * 0.6;
    this.chute.rotation.z = Math.sin(t * 1.4) * 0.08;
    this.chute.rotation.x = Math.cos(t * 1.1) * 0.05;
    this.character.position.copy(this.position);
    this.character.rotation.y = this.yaw;
    // Tuck legs while descending
    this.character.userData.legL.rotation.x = 0.25 + Math.sin(t * 2) * 0.05;
    this.character.userData.legR.rotation.x = 0.35 - Math.sin(t * 2) * 0.05;
    this.character.userData.armL.rotation.x = -0.4;
    this.character.userData.armR.rotation.x = -0.4;
    return t0 >= 1;
  }

  groundHeight(x, z) {
    let g = this.world.heightAt(x, z);
    for (const s of this.world.surfaces) {
      if (x > s.minX && x < s.maxX && z > s.minZ && z < s.maxZ) {
        if (this.position.y > s.y - 1.4) g = Math.max(g, s.y);
      }
    }
    return g;
  }

  update(dt, input, camera) {
    if (!this.alive || this.dropping) return;
    this.fireCooldown = Math.max(0, this.fireCooldown - dt);
    this.switchTimer = Math.max(0, this.switchTimer - dt);
    this.cameraShake = Math.max(0, this.cameraShake - dt * 2.6);
    this.recoilPitch = damp(this.recoilPitch, 0, 9, dt);
    this.recoilYaw = damp(this.recoilYaw, 0, 8, dt);

    if (this.reloadTimer > 0) {
      this.reloadTimer -= dt;
      if (this.reloadTimer <= 0) this.finishReload();
    }
    if (this.healTimer > 0) {
      this.healTimer -= dt;
      if (this.healTimer <= 0) {
        const heal = MATCH.medHeal;
        this.health = Math.min(MATCH.maxHealth, this.health + heal);
        this.healTimer = 0;
      }
    }

    const w = this.weapon;
    this.crouching = !!input.crouch;
    this.aiming = !!input.aim && this.reloadTimer <= 0 && this.healTimer <= 0 && !input.sprint;
    this.sprinting = !!input.sprint && !this.crouching && !this.aiming && input.moveMag > 0.1;
    const ground = this.groundHeight(this.position.x, this.position.z);
    const inWater = ground < this.world.waterLevel - 0.3 && this.position.y < 1.2;
    this.isSwimming = inWater;

    let speed = 6.4;
    if (this.crouching) speed = 3.15;
    if (this.aiming) speed = 4.1;
    if (this.sprinting) speed = 9.2;
    if (this.isSwimming) speed = 3.4;
    if (this.reloadTimer > 0 || this.healTimer > 0) speed *= 0.82;

    const forward = new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
    const right = new THREE.Vector3(-forward.z, 0, forward.x);
    const desired = new THREE.Vector3();
    if (input.moveMag > 0.02) {
      desired.addScaledVector(right, input.moveX).addScaledVector(forward, input.moveZ);
      if (desired.lengthSq() > 1) desired.normalize();
      desired.multiplyScalar(speed * Math.min(1, input.moveMag));
    }
    const accel = this.grounded ? 38 : 8;
    this.velocity.x = damp(this.velocity.x, desired.x, accel * 0.35, dt);
    this.velocity.z = damp(this.velocity.z, desired.z, accel * 0.35, dt);

    // Jump
    if (input.jump && this.grounded && !this.isSwimming && this.crouching === false) {
      this.velocity.y = 6.7;
      this.grounded = false;
      input.jump = false;
    }

    const wasGrounded = this.grounded;
    if (!this.isSwimming) {
      this.velocity.y -= 19.5 * dt;
    } else {
      this.velocity.y = 0;
    }
    this.position.x += this.velocity.x * dt;
    this.position.z += this.velocity.z * dt;
    this.position.y += this.velocity.y * dt;

    this.resolveCollisions(this.position);

    const newGround = this.groundHeight(this.position.x, this.position.z);
    if (this.isSwimming) {
      this.position.y = damp(this.position.y, this.world.waterLevel - 0.62 + Math.sin(performance.now() * 0.002) * 0.05, 6, dt);
      this.velocity.y = 0;
      this.grounded = false;
    } else if (this.position.y <= newGround) {
      this.position.y = newGround;
      if (this.velocity.y < -9) this.cameraShake = 0.35;
      this.velocity.y = 0;
      this.grounded = true;
    } else {
      this.grounded = false;
    }
    if (this.grounded && !wasGrounded && this.velocity.y < -3) this.cameraShake = Math.min(0.4, Math.abs(this.velocity.y) * 0.025);

    // world bounds
    this.position.x = clamp(this.position.x, -218, 218);
    this.position.z = clamp(this.position.z, -218, 218);

    this.moveAmount = Math.hypot(this.velocity.x, this.velocity.z);
    const animSpeed = this.moveAmount / 6.4;
    this.walkPhase += dt * (this.isSwimming ? 3 : 5.4 + this.moveAmount * 1.2);
    this.animate(dt, animSpeed);

    this.aimAmount = damp(this.aimAmount, this.aiming ? 1 : 0, 12, dt);
    this.character.position.copy(this.position);
    this.character.rotation.y = this.yaw;
    this.updateCamera(dt, camera);

    if (this.aiming && w.id === 'sniper') this.cameraShake = Math.max(this.cameraShake, 0.02);
  }

  resolveCollisions(p) {
    const r = this.crouching ? 0.34 : this.radius;
    for (const c of this.world.colliders) {
      if (p.y + 1.65 < c.minY + 0.02 || p.y > c.maxY - 0.02) continue;
      const nx = clamp(p.x, c.minX, c.maxX);
      const nz = clamp(p.z, c.minZ, c.maxZ);
      let dx = p.x - nx, dz = p.z - nz;
      const d2 = dx * dx + dz * dz;
      if (d2 > r * r) continue;
      if (d2 < 1e-8) {
        const left = p.x - c.minX, right = c.maxX - p.x, front = p.z - c.minZ, back = c.maxZ - p.z;
        const m = Math.min(left, right, front, back);
        if (m === left) p.x = c.minX - r;
        else if (m === right) p.x = c.maxX + r;
        else if (m === front) p.z = c.minZ - r;
        else p.z = c.maxZ + r;
      } else {
        const d = Math.sqrt(d2);
        p.x = nx + (dx / d) * r;
        p.z = nz + (dz / d) * r;
      }
    }
  }

  animate(dt, animSpeed) {
    const u = this.character.userData;
    const t = performance.now() * 0.001;
    const crouchTarget = this.crouching ? -0.26 : 0;
    u.body.position.y = damp(u.body.position.y, crouchTarget, 13, dt);
    const swing = Math.sin(this.walkPhase) * Math.min(1, animSpeed) * (this.isSwimming ? 0.35 : 0.65);
    if (!this.grounded) {
      u.legL.rotation.x = damp(u.legL.rotation.x, -0.45, 10, dt);
      u.legR.rotation.x = damp(u.legR.rotation.x, 0.25, 10, dt);
    } else {
      u.legL.rotation.x = damp(u.legL.rotation.x, swing, 15, dt);
      u.legR.rotation.x = damp(u.legR.rotation.x, -swing, 15, dt);
    }
    const aim = this.aimAmount;
    const bob = Math.sin(this.walkPhase * 2) * 0.012 * animSpeed;
    u.torso.position.y = 1.3 + bob;
    u.head.position.y = 1.73 + bob;
    u.armL.rotation.x = damp(u.armL.rotation.x, -1.24 - aim * 0.12, 12, dt);
    u.armL.rotation.z = damp(u.armL.rotation.z, 0.18 + aim * 0.1, 12, dt);
    u.armR.rotation.x = damp(u.armR.rotation.x, -1.16 - aim * 0.1, 12, dt);
    u.armR.rotation.z = damp(u.armR.rotation.z, -0.15, 12, dt);
    u.weaponMount.rotation.x = damp(u.weaponMount.rotation.x, this.reloadTimer > 0 ? -0.45 : 0, 10, dt);
    u.weaponMount.position.y = damp(u.weaponMount.position.y, this.aiming ? 1.43 : 1.35, 10, dt);
    u.weaponMount.position.x = damp(u.weaponMount.position.x, this.aiming ? 0.09 : 0.15, 10, dt);
    if (this.reloadTimer > 0) {
      u.armL.rotation.z = 0.4 + Math.sin(t * 17) * 0.25;
      u.armR.rotation.z = -0.35 + Math.sin(t * 17) * 0.18;
    }
  }

  updateCamera(dt, camera) {
    const w = this.weapon;
    const pitch = clamp(this.pitch + this.recoilPitch, -1.25, 1.25);
    const yaw = this.yaw + this.recoilYaw;
    const dir = new THREE.Vector3(-Math.sin(yaw) * Math.cos(pitch), Math.sin(pitch), -Math.cos(yaw) * Math.cos(pitch));
    const right = new THREE.Vector3(-dir.z, 0, dir.x).normalize();
    const shoulder = this.aiming ? 0.62 : 0.72;
    const target = this.position.clone().add(new THREE.Vector3(0, this.crouching ? 1.22 : 1.58, 0)).addScaledVector(right, shoulder * 0.6);
    let dist = this.aiming ? 2.85 : 5.15;
    if (this.sprinting) dist = 5.45;
    if (this.isSwimming) dist = 4.2;
    const desired = target.clone().addScaledVector(dir, -dist);
    desired.y += 0.25;
    // camera collision
    const toCam = desired.clone().sub(target);
    const len = toCam.length();
    toCam.normalize();
    const hit = this.world.raycastWorld(target, toCam, len + 0.15);
    if (hit && hit.distance < len) {
      desired.copy(target).addScaledVector(toCam, Math.max(0.4, hit.distance - 0.25));
    }
    const ground = this.world.heightAt(desired.x, desired.z) + 0.55;
    if (desired.y < ground) desired.y = ground;
    if (this.cameraShake > 0) {
      desired.x += (Math.random() - 0.5) * this.cameraShake * 0.18;
      desired.y += (Math.random() - 0.5) * this.cameraShake * 0.18;
    }
    camera.position.lerp(desired, 1 - Math.exp(-16 * dt));
    const look = target.clone().addScaledVector(dir, 12);
    camera.lookAt(look);
    const targetFov = this.aiming ? (w.id === 'sniper' ? 32 : 46) : this.sprinting ? 76 : 67;
    camera.fov = damp(camera.fov, targetFov, 10, dt);
    camera.updateProjectionMatrix();
  }

  getForward() {
    const pitch = clamp(this.pitch + this.recoilPitch, -1.25, 1.25);
    const yaw = this.yaw + this.recoilYaw;
    return new THREE.Vector3(-Math.sin(yaw) * Math.cos(pitch), Math.sin(pitch), -Math.cos(yaw) * Math.cos(pitch));
  }

  getMuzzleWorld() {
    if (!this.weaponModel) return this.position.clone().add(new THREE.Vector3(0, 1.5, 0));
    const muzzle = this.weaponModel.userData.muzzle;
    this.character.updateMatrixWorld(true);
    const p = new THREE.Vector3();
    muzzle.getWorldPosition(p);
    return p;
  }

  getSpread() {
    const w = this.weapon;
    let spread = w.spread;
    if (this.aiming) spread = w.adsSpread;
    else if (this.moveAmount > 2) spread = w.moveSpread;
    if (this.crouching) spread *= 0.72;
    if (!this.grounded) spread *= 1.7;
    if (this.isSwimming) spread *= 1.5;
    return spread;
  }

  canFire() {
    return this.alive && !this.dropping && this.fireCooldown <= 0 && this.reloadTimer <= 0 && this.switchTimer <= 0 && this.healTimer <= 0;
  }

  fire() {
    if (!this.canFire()) return null;
    const slot = this.slot;
    const w = this.weapon;
    if (slot.mag <= 0) {
      this.startReload();
      return null;
    }
    slot.mag -= 1;
    this.fireCooldown = 60 / w.rpm;
    this.recoilPitch += w.recoil * (this.aiming ? 0.64 : 1) * (this.crouching ? 0.7 : 1);
    this.recoilYaw += (Math.random() - 0.5) * w.recoil * 0.85;
    this.cameraShake = Math.min(0.65, this.cameraShake + w.recoil * 5);
    return { weapon: w, spread: this.getSpread(), pellets: w.pellets, damage: w.damage * (slot.rarity === 'legendary' ? 1.18 : slot.rarity === 'epic' ? 1.1 : slot.rarity === 'rare' ? 1.04 : 1), slot };
  }

  startReload() {
    if (this.reloadTimer > 0 || this.dropping) return false;
    const slot = this.slot;
    const w = this.weapon;
    if (w.id === 'melee' || slot.mag >= w.mag || slot.reserve <= 0) return false;
    this.reloadTimer = w.reload;
    this.reloadTotal = w.reload;
    return true;
  }

  finishReload() {
    const slot = this.slot;
    const w = this.weapon;
    const need = w.mag - slot.mag;
    const take = Math.min(need, slot.reserve);
    slot.mag += take;
    slot.reserve -= take;
    this.reloadTimer = 0;
  }

  switchWeapon(index) {
    if (index === this.currentSlot || index < 0 || index > 2 || this.switchTimer > 0 || this.dropping) return false;
    this.currentSlot = index;
    this.reloadTimer = 0;
    this.switchTimer = 0.32;
    this.updateWeaponModel();
    return true;
  }

  nextWeapon() {
    for (let i = 1; i <= 3; i++) {
      const idx = (this.currentSlot + i) % 3;
      if (this.slots[idx] && this.slots[idx].id !== 'melee') {
        this.switchWeapon(idx);
        return;
      }
    }
  }

  startHeal() {
    if (this.medkits <= 0 || this.health >= MATCH.maxHealth || this.healTimer > 0 || this.reloadTimer > 0 || this.dropping) return false;
    this.medkits -= 1;
    this.healTimer = MATCH.medUseTime;
    this.healTotal = MATCH.medUseTime;
    return true;
  }

  giveWeapon(id, rarity = 'common', attachments = []) {
    const w = WEAPONS[id];
    if (!w) return false;
    if (id === 'melee') return false;
    const slotData = { id, mag: w.mag, reserve: w.reserve, rarity, attachments };
    // Prefer empty weapon slot
    const empty = this.slots.findIndex((s, i) => i < 2 && (!s || s.id === 'melee'));
    if (empty >= 0 && this.slots[empty]?.id === 'melee') {
      this.slots[empty] = slotData;
      if (this.currentSlot === empty) this.updateWeaponModel();
      return true;
    }
    // Replace secondary first if current is primary, otherwise current
    const target = this.currentSlot === 0 ? 1 : this.currentSlot;
    this.slots[target] = slotData;
    if (this.currentSlot === target) this.updateWeaponModel();
    return true;
  }

  giveAmmo(amount = 30) {
    const slot = this.slots.find(s => s && s.id !== 'melee');
    if (!slot) return false;
    const w = WEAPONS[slot.id];
    slot.reserve = Math.min(w.reserve * 2, slot.reserve + amount);
    return true;
  }

  giveArmor(amount = 25) {
    this.armor = Math.min(this.maxArmor, this.armor + amount);
  }

  giveMedkit(n = 1) {
    this.medkits = Math.min(5, this.medkits + n);
  }

  giveGrenade(n = 1) {
    this.grenades = Math.min(3, this.grenades + n);
  }

  takeDamage(amount, sourcePos = null, zone = false) {
    if (!this.alive) return 0;
    let final = amount;
    if (!zone && this.armor > 0) {
      const absorbed = Math.min(this.armor, amount * 0.55);
      this.armor -= absorbed;
      final = amount - absorbed;
    }
    this.health -= final;
    this.lastDamageTime = 0;
    this.cameraShake = Math.min(0.8, this.cameraShake + 0.24);
    if (this.health <= 0) {
      this.health = 0;
      this.alive = false;
      this.deathTime = 0;
      this.character.userData.body.rotation.z = -1.35;
      this.character.userData.body.position.y = -0.2;
    }
    return final;
  }

  updateDeath(dt) {
    this.deathTime += dt;
    this.character.userData.body.rotation.z = damp(this.character.userData.body.rotation.z, -1.45, 8, dt);
    this.character.userData.body.position.y = damp(this.character.userData.body.position.y, 0.1, 8, dt);
  }
}

import * as THREE from 'three';
import { BOT_NAMES, BOT_PALETTES, WEAPONS, OPERATORS } from './data.js';
import { clamp, damp, dampAngle, mulberry32, makeCanvas } from './utils.js';
import { createOperator, createWeaponModel, createBotHealthBar } from './models.js';

function nameSprite(name) {
  const c = makeCanvas(256, 64);
  const ctx = c.getContext('2d');
  ctx.clearRect(0, 0, 256, 64);
  ctx.font = '700 27px "Arial Narrow", Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.strokeStyle = 'rgba(0,0,0,.72)';
  ctx.lineWidth = 5;
  ctx.strokeText(name, 128, 32);
  ctx.fillStyle = 'rgba(255,235,220,.92)';
  ctx.fillText(name, 128, 32);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, depthTest: false }));
  sp.scale.set(1.55, 0.39, 1);
  sp.renderOrder = 10;
  return sp;
}

export class BotManager {
  constructor(scene, world, effects, audio, game) {
    this.scene = scene;
    this.world = world;
    this.effects = effects;
    this.audio = audio;
    this.game = game;
    this.bots = [];
    this.rnd = mulberry32(0xB077);
    this.names = [...BOT_NAMES].sort(() => this.rnd() - 0.5);
    this.remoteKillTimer = 14;
    this.player = null;
    this.camera = null;
    this.aliveCount = 0;
    this._tmpMuzzle = new THREE.Vector3();
  }

  spawn(count, playerSpawn, zoneCenter = { x: 0, z: 0 }, zoneRadius = 170) {
    for (let i = 0; i < count; i++) {
      let x, z, tries = 0;
      do {
        const a = this.rnd() * Math.PI * 2;
        const rad = 22 + Math.sqrt(this.rnd()) * (zoneRadius - 45);
        x = zoneCenter.x + Math.cos(a) * rad;
        z = zoneCenter.z + Math.sin(a) * rad;
        tries++;
      } while (tries < 40 && (this.world.heightAt(x, z) < 1.4 || Math.hypot(x - playerSpawn.x, z - playerSpawn.z) < 24));
      const palette = BOT_PALETTES[i % BOT_PALETTES.length];
      const p = { ...palette, accent: palette.accent };
      const group = createOperator(p, palette.accent, true);
      group.scale.setScalar(0.97);
      const weaponIds = ['ar', 'smg', 'shotgun', 'ar', 'sniper', 'lmg', 'ar', 'smg', 'pistol'];
      const wid = weaponIds[Math.floor(this.rnd() * weaponIds.length)];
      const wpn = createWeaponModel(wid, palette.accent, 0.78);
      group.userData.weaponMount.add(wpn);
      group.position.set(x, this.world.heightAt(x, z) + 0.05, z);
      group.rotation.y = this.rnd() * Math.PI * 2;
      this.scene.add(group);
      const bar = createBotHealthBar();
      this.scene.add(bar);
      const label = nameSprite(this.names[i % this.names.length]);
      this.scene.add(label);
      const weapon = WEAPONS[wid];
      const bot = {
        id: i, name: this.names[i % this.names.length], group, bar, label, weapon, weaponId: wid,
        health: 100, maxHealth: 100, armor: 15 + Math.floor(this.rnd() * 30),
        position: group.position, yaw: group.rotation.y, anchor: { x, z },
        alive: true, state: 'patrol', target: null, think: this.rnd() * 0.3,
        fireCd: 0.6 + this.rnd() * 1.0, deathTime: 0, walkPhase: this.rnd() * 6,
        speed: 3.5 + this.rnd() * 1.7, los: false, lastHitBy: null,
        strafe: this.rnd() > 0.5 ? 1 : -1, strafeTimer: 1 + this.rnd() * 2,
        skill: 0.36 + this.rnd() * 0.28
      };
      group.userData.bot = bot;
      this.bots.push(bot);
    }
    this.aliveCount = this.bots.length;
    return this.bots;
  }

  reset() {
    for (const b of this.bots) {
      this.scene.remove(b.group);
      this.scene.remove(b.bar);
      this.scene.remove(b.label);
    }
    this.bots = [];
    this.aliveCount = 0;
  }

  setPlayer(player, camera) {
    this.player = player;
    this.camera = camera;
  }

  think(bot, player) {
    const pos = bot.position;
    const candidates = [];
    if (player.alive) candidates.push({ kind: 'player', obj: player, pos: player.position, name: 'YOU' });
    for (const other of this.bots) {
      if (other === bot || !other.alive) continue;
      const d = pos.distanceTo(other.position);
      if (d < 50) candidates.push({ kind: 'bot', obj: other, pos: other.position, name: other.name, d });
    }
    let best = null, bestScore = Infinity;
    for (const c of candidates) {
      const d = c.d ?? pos.distanceTo(c.pos);
      if (c.kind === 'player' && d > 58) continue;
      if (d > 54) continue;
      let score = d;
      if (c.kind === 'player') score *= 0.82;
      if (score < bestScore) { bestScore = score; best = c; }
    }
    bot.target = best;
    if (best) {
      const d = bestScore;
      const to = new THREE.Vector3(best.pos.x - pos.x, (best.kind === 'player' ? 1.4 : 1.2), best.pos.z - pos.z);
      const eye = new THREE.Vector3(pos.x, pos.y + 1.55, pos.z);
      const dir = to.clone().normalize();
      const hit = this.world.raycastWorld(eye, dir, d - 0.4);
      bot.los = !hit;
      bot.aimYaw = Math.atan2(-(best.pos.x - pos.x), -(best.pos.z - pos.z));
      bot.aimPitch = Math.atan2(best.pos.y + 1.3 - (pos.y + 1.55), Math.max(0.4, d));
      bot.state = d < 3.0 ? 'retreat' : 'engage';
      bot.engageDist = d;
    } else {
      bot.los = false;
      if (this.world.heightAt(pos.x, pos.z) < 0.8) bot.state = 'patrol';
      bot.state = bot.state === 'engage' ? 'patrol' : bot.state;
    }
  }

  update(dt, t, player, camera, zone) {
    this.player = player;
    this.camera = camera;
    this.aliveCount = 0;
    const zoneDist = (x, z) => Math.hypot(x - zone.x, z - zone.z);
    for (const bot of this.bots) {
      if (!bot.alive) {
        bot.deathTime += dt;
        if (bot.deathTime < 6) {
          const u = bot.group.userData;
          u.body.rotation.z = damp(u.body.rotation.z, -1.5, 7, dt);
          u.body.position.y = damp(u.body.position.y, 0.1, 7, dt);
          u.legL.rotation.x = damp(u.legL.rotation.x, -0.4, 5, dt);
          u.legR.rotation.x = damp(u.legR.rotation.x, 0.2, 5, dt);
        } else {
          bot.group.visible = false;
          bot.bar.visible = false;
          bot.label.visible = false;
        }
        continue;
      }
      this.aliveCount++;
      bot.think -= dt;
      bot.fireCd = Math.max(0, bot.fireCd - dt);
      bot.strafeTimer -= dt;
      if (bot.strafeTimer <= 0) {
        bot.strafe *= -1;
        bot.strafeTimer = 1.2 + this.rnd() * 2.6;
      }
      if (bot.think <= 0) {
        this.think(bot, player);
        bot.think = 0.28 + this.rnd() * 0.26;
      }

      const out = zoneDist(bot.position.x, bot.position.z) > zone.radius;
      let move = new THREE.Vector3();
      let faceYaw = bot.yaw;
      const target = bot.target;
      if (out) {
        const toCenter = new THREE.Vector3(zone.x - bot.position.x, 0, zone.z - bot.position.z).normalize();
        move.copy(toCenter).multiplyScalar(1.2);
        faceYaw = Math.atan2(-move.x, -move.z);
        bot.state = 'zone';
      } else if (target && bot.los) {
        const dx = target.pos.x - bot.position.x, dz = target.pos.z - bot.position.z;
        const d = Math.hypot(dx, dz);
        const nx = dx / Math.max(0.001, d), nz = dz / Math.max(0.001, d);
        const preferred = bot.weaponId === 'shotgun' ? 8 : bot.weaponId === 'sniper' ? 29 : bot.weaponId === 'smg' ? 13 : 21;
        if (d > preferred + 4) {
          move.set(nx, 0, nz).multiplyScalar(1.0);
        } else if (d < preferred - 5) {
          move.set(-nx, 0, -nz).multiplyScalar(0.85);
        }
        const strafe = new THREE.Vector3(-nz, 0, nx).multiplyScalar(bot.strafe * 0.55);
        move.add(strafe);
        faceYaw = Math.atan2(-dx, -dz);
        this.tryShoot(bot, target, player, d, camera);
      } else {
        // patrol around anchor / drift toward zone
        const toAnchor = new THREE.Vector3(bot.anchor.x - bot.position.x, 0, bot.anchor.z - bot.position.z);
        if (toAnchor.length() > 8) {
          move.copy(toAnchor).normalize().multiplyScalar(0.42);
          faceYaw = Math.atan2(-move.x, -move.z);
        } else {
          const a = t * 0.13 + bot.id * 1.7;
          move.set(Math.cos(a) * 0.18, 0, Math.sin(a) * 0.18);
          if (Math.random() < 0.01) bot.anchor = { x: clamp(bot.position.x + (this.rnd() - 0.5) * 25, -170, 170), z: clamp(bot.position.z + (this.rnd() - 0.5) * 25, -170, 170) };
        }
      }

      // avoid water
      const ahead = this.world.heightAt(bot.position.x + move.x * 2, bot.position.z + move.z * 2);
      if (ahead < 0.7) {
        move.set(-move.z, 0, move.x).multiplyScalar(0.5);
      }
      // separation from other bots
      for (const other of this.bots) {
        if (other === bot || !other.alive) continue;
        const dx = bot.position.x - other.position.x, dz = bot.position.z - other.position.z;
        const d2 = dx * dx + dz * dz;
        if (d2 < 2.6 && d2 > 0.0001) {
          const inv = 1 / Math.sqrt(d2);
          move.x += dx * inv * 0.45;
          move.z += dz * inv * 0.45;
        }
      }
      if (move.lengthSq() > 0.001) {
        move.normalize();
        const speed = (target && bot.los ? 3.7 : 2.4) * (out ? 1.5 : 1) * (bot.weaponId === 'sniper' ? 0.88 : 1);
        bot.position.x += move.x * speed * dt;
        bot.position.z += move.z * speed * dt;
      }
      bot.position.x = clamp(bot.position.x, -200, 200);
      bot.position.z = clamp(bot.position.z, -200, 200);
      this.resolve(bot);
      const ground = this.world.heightAt(bot.position.x, bot.position.z);
      if (ground > this.world.waterLevel - 0.2) {
        bot.position.y = damp(bot.position.y, ground, 16, dt);
      } else {
        bot.position.y = damp(bot.position.y, this.world.waterLevel - 0.6, 5, dt);
      }
      bot.yaw = dampAngle(bot.yaw, faceYaw, 8, dt);
      bot.group.position.copy(bot.position);
      bot.group.rotation.y = bot.yaw;
      const moveAmt = Math.hypot(move.x, move.z);
      bot.walkPhase += dt * (5 + moveAmt * 4.5);
      this.animate(bot, moveAmt, dt);

      // health bar follow
      const camPos = camera.position;
      const dist = camPos.distanceTo(bot.position);
      const show = dist < 82;
      bot.bar.visible = show;
      bot.label.visible = show && dist < 48;
      if (show) {
        bot.bar.position.set(bot.position.x, bot.position.y + 2.18, bot.position.z);
        bot.bar.quaternion.copy(camera.quaternion);
        const ratio = clamp(bot.health / bot.maxHealth, 0, 1);
        bot.bar.userData.fill.scale.x = Math.max(0.001, ratio);
        bot.bar.userData.fill.position.x = -bot.bar.userData.width * (1 - ratio) / 2;
        bot.bar.userData.fill.material.color.setHex(ratio > 0.5 ? 0x6ce9c7 : ratio > 0.25 ? 0xffb34d : 0xff5a3c);
        bot.label.position.set(bot.position.x, bot.position.y + 2.45, bot.position.z);
        bot.label.quaternion.copy(camera.quaternion);
      }

      // zone damage ticks
      if (out && Math.random() < dt * 0.75) {
        this.damage(bot, zone.damage * 1.5, 'ZONE', null, false);
      }

      // Ambient squads trade shots to keep the island alive
      if (dist > 78 && target && Math.random() < dt * 0.018) {
        this.effects.tracer(bot.position.clone().add(new THREE.Vector3(0, 1.5, 0)), target.pos.clone().add(new THREE.Vector3(0, 1.2, 0)), 0xffcf90);
        this.audio.shot(bot.weaponId, 40);
      }
    }

    // Remote combat simulation so the alive counter falls outside the player's view.
    this.remoteKillTimer -= dt;
    if (this.remoteKillTimer <= 0) {
      this.remoteKillTimer = 12 + this.rnd() * 10;
      const alive = this.bots.filter(b => b.alive && (!player || b.position.distanceTo(player.position) > 85));
      if (alive.length > 1) {
        const victim = alive[Math.floor(this.rnd() * alive.length)];
        const killerPool = alive.filter(b => b !== victim);
        const killer = killerPool[Math.floor(this.rnd() * killerPool.length)];
        this.damage(victim, 1000, killer.name, killer, true);
      }
    }
  }

  tryShoot(bot, target, player, dist, camera) {
    if (bot.fireCd > 0) return;
    const w = bot.weapon;
    const rate = w.id === 'sniper' ? 1.9 : w.id === 'shotgun' ? 1.1 : w.id === 'smg' ? 0.17 : 0.32;
    bot.fireCd = rate * (0.75 + this.rnd() * 0.7);
    if (dist > w.range * 0.72) return;
    const eye = bot.position.clone().add(new THREE.Vector3(0, 1.48, 0));
    const aim = target.pos.clone().add(new THREE.Vector3(0, target.kind === 'player' ? 1.25 : 1.18, 0));
    const dir = aim.clone().sub(eye).normalize();
    const right = new THREE.Vector3(-dir.z, 0, dir.x);
    const miss = 0.55 + dist * 0.018;
    const errX = (this.rnd() - 0.5) * miss;
    const errY = (this.rnd() - 0.5) * miss * 0.6;
    const end = aim.clone().addScaledVector(right, errX).add(new THREE.Vector3(0, errY, 0));
    const hitChance = clamp(bot.skill - dist * 0.008 - (target.kind === 'player' ? 0.06 : 0) - (player && player.aiming ? 0.04 : 0), 0.12, 0.7);
    const hit = this.rnd() < hitChance;
    const muzzle = bot.group.userData.weaponMount.getWorldPosition(new THREE.Vector3());
    muzzle.y += 0.1;
    this.effects.muzzle(muzzle, 0xffbd6a, 0.75);
    const hitPoint = hit ? aim : end;
    this.effects.tracer(muzzle, hitPoint, 0xffd49a);
    const distToCam = camera.position.distanceTo(bot.position);
    this.audio.shot(w.id, distToCam);
    if (hit) {
      const dmg = (w.damage * (0.42 + this.rnd() * 0.26)) * (target.kind === 'player' ? 0.72 : 0.55);
      if (target.kind === 'player') {
        this.game.damagePlayer(dmg, bot, false);
      } else {
        this.damage(target.obj, dmg, bot.name, bot, false);
      }
      this.effects.impact(hitPoint, null, 'flesh');
    } else {
      this.effects.impact(end, null, 'world');
    }
  }

  animate(bot, moveAmt, dt) {
    const u = bot.group.userData;
    const swing = Math.sin(bot.walkPhase) * Math.min(1, moveAmt) * 0.6;
    u.legL.rotation.x = damp(u.legL.rotation.x, swing, 12, dt);
    u.legR.rotation.x = damp(u.legR.rotation.x, -swing, 12, dt);
    u.armL.rotation.x = damp(u.armL.rotation.x, -1.24, 10, dt);
    u.armR.rotation.x = damp(u.armR.rotation.x, -1.18, 10, dt);
    u.armL.rotation.z = damp(u.armL.rotation.z, 0.18, 10, dt);
    u.armR.rotation.z = damp(u.armR.rotation.z, -0.15, 10, dt);
    u.torso.position.y = 1.3 + Math.sin(bot.walkPhase * 2) * 0.012 * moveAmt;
  }

  resolve(bot) {
    const r = 0.36;
    const p = bot.position;
    for (const c of this.world.colliders) {
      if (p.y + 1.7 < c.minY || p.y > c.maxY) continue;
      const nx = clamp(p.x, c.minX, c.maxX);
      const nz = clamp(p.z, c.minZ, c.maxZ);
      let dx = p.x - nx, dz = p.z - nz;
      const d2 = dx * dx + dz * dz;
      if (d2 > r * r) continue;
      if (d2 < 1e-8) {
        const left = p.x - c.minX, right = c.maxX - p.x, front = p.z - c.minZ, back = c.maxZ - p.z;
        const m = Math.min(left, right, front, back);
        if (m === left) p.x = c.minX - r;
        else if (m === right) p.x = c.maxX + r;
        else if (m === front) p.z = c.minZ - r;
        else p.z = c.maxZ + r;
      } else {
        const d = Math.sqrt(d2);
        p.x = nx + dx / d * r;
        p.z = nz + dz / d * r;
      }
    }
  }

  damage(bot, amount, sourceName, sourceBot, remote = false) {
    if (!bot.alive) return;
    let dmg = amount;
    if (bot.armor > 0 && amount < 500) {
      const absorbed = Math.min(bot.armor, amount * 0.4);
      bot.armor -= absorbed;
      dmg = amount - absorbed;
    }
    bot.health -= dmg;
    bot.lastHitBy = sourceName;
    if (!remote && this.player && this.player.position.distanceTo(bot.position) < 50) {
      bot.think = 0;
    }
    if (bot.health <= 0) {
      this.kill(bot, sourceName, sourceBot, remote);
    }
  }

  kill(bot, sourceName, sourceBot, remote = false) {
    if (!bot.alive) return;
    bot.alive = false;
    bot.health = 0;
    bot.deathTime = 0;
    bot.bar.visible = false;
    bot.label.visible = false;
    bot.group.userData.body.rotation.z = -0.2;
    this.game.onBotKilled(bot, sourceName, sourceBot, remote);
  }

  alertAround(pos, radius) {
    for (const b of this.bots) {
      if (b.alive && b.position.distanceTo(pos) < radius && !b.target) b.think = 0;
    }
  }

  nearestAlive(pos, max = 999) {
    let best = null, bd = max;
    for (const b of this.bots) {
      if (!b.alive) continue;
      const d = b.position.distanceTo(pos);
      if (d < bd) { bd = d; best = b; }
    }
    return best;
  }

  getAlive() { return this.bots.filter(b => b.alive); }
}

