import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await page.goto('http://localhost:3002', { waitUntil: 'load' })
const btn = page.locator('#playBtn')
const t0 = Date.now()
for (let i = 0; i < 30; i++) {
  const info = await btn.evaluate(el => {
    const r = el.getBoundingClientRect()
    const style = getComputedStyle(el)
    const lobby = document.getElementById('lobby')
    return { x: r.x, y: r.y, w: r.width, h: r.height, op: style.opacity, vis: style.visibility, disp: style.display, lobbyHidden: lobby.classList.contains('hidden'), lobbyOp: getComputedStyle(lobby).opacity, top: (() => { const e = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2); return e?.id || e?.className || e?.tagName })() }
  }).catch(e => ({ error: e.message }))
  console.log(Date.now() - t0, JSON.stringify(info))
  await page.waitForTimeout(100)
}
await browser.close()

