import { createRequire } from 'node:module'
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.on('pageerror', e => console.error('PAGEERROR', e.message))
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForFunction(() => window.__BW_READY__ === true, null, { timeout: 60000 })
const dataUrl = await page.evaluate(() => {
  const g = window.__BATTLEWORLD__
  g.setMenuCamera(0)
  g.renderer.render(g.scene, g.camera)
  return g.renderer.domElement.toDataURL('image/png')
})
const base64 = dataUrl.replace(/^data:image\/png;base64,/, '')
mkdirSync('assets', { recursive: true })
writeFileSync(join('assets', 'lobby-island.png'), Buffer.from(base64, 'base64'))
console.log('wrote', Buffer.from(base64, 'base64').length, 'bytes')
await browser.close()

